<input class="w-full pl-11 pr-space-md py-2.5 bg-soft-bg text-on-surface font-body-md text-body-md rounded-lg border border-surface-container-high focus:outline-none focus:bg-surface-container-lowest focus:border-sapphire focus:ring-1 focus:ring-sapphire transition-all duration-200 placeholder:text-outline" id="userInput" placeholder="contoh: admin.utama@sekolah.sch.id / 198204..." required="" type="text">
</div>
</div>
<!-- Field 2: Password -->
<div>
