              Kata Sandi
            </label>
<span class="font-label-sm text-label-sm text-on-surface-variant">Tersandi Kuat</span>
</div>
<div class="relative">
<div class="absolute inset-y-0 left-0 pl-space-md flex items-center pointer-events-none text-sapphire">
<span class="material-symbols-outlined text-[20px]">lock</span>
</div>
<input class="w-full pl-11 pr-11 py-2.5 bg-soft-bg text-on-surface font-body-md text-body-md rounded-lg border border-surface-container-high focus:outline-none focus:bg-surface-container-lowest focus:border-sapphire focus:ring-1 focus:ring-sapphire transition-all duration-200 placeholder:text-outline" id="passInput" placeholder="Masukkan kata sandi terdaftar" required="" type="password">
<button aria-label="Toggle password view" class="absolute inset-y-0 right-0 pr-space-md flex items-center text-outline hover:text-sapphire transition-colors" onclick="togglePasswordVisibility()" type="button">
