<span class="material-symbols-outlined text-[20px]">password</span>
</div>

</div>
<p class="mt-1 text-[11px] text-on-surface-variant flex items-center gap-1">
<span class="material-symbols-outlined text-[14px] text-ocean">info</span>
            Token akses diterbitkan oleh administrator sistem / otentikator.
          </p>
</div>
<!-- Opsi Remember Me & 2FA Terverifikasi -->
