<!-- Interactive Scripts -->
<script>
  const roleConfigs = {
    admin: {
      rolePill: 'Super Admin',
      title: 'Masuk ke Sistem BBCashvia',
      desc: '<strong>Super Administrator:</strong> Konfigurasi sistem global, master siswa & kelas, hak otorisasi rekening, serta riwayat audit transaksi menyeluruh.',
      descIcon: 'admin_panel_settings',
      identityLabel: 'NIP / Email Administrator',
      identityPlaceholder: 'contoh: admin.utama@sekolah.sch.id / 198204...',
      identityIcon: 'badge',
      identityBadge: 'Format NIP / Email Sekolah'
    },
    bendahara: {
      rolePill: 'Bendahara Kas',
      title: 'Masuk ke Sistem BBCashvia',
      desc: '<strong>Bendahara Kas:</strong> Input penerimaan setoran kas siswa, validasi kuitansi pengeluaran operasional, dan cetak pembukuan kas umum (BKU).',
      descIcon: 'account_balance_wallet',
      identityLabel: 'ID Petugas / No. Registrasi Bendahara',
      identityPlaceholder: 'contoh: BND-2024-XIA-09 atau email bendahara',
      identityIcon: 'pin',
      identityBadge: 'ID Khusus Kasir / Petugas'
    },
    viewer: {
      rolePill: 'Viewer / Ortu',
      title: 'Masuk ke Sistem BBCashvia',
      desc: '<strong>Viewer (Kepala Sekolah / Wali Murid / Auditor):</strong> Pemantauan saldo kas real-time, status iuran siswa, dan transparansi laporan keuangan.',
      descIcon: 'visibility',
      identityLabel: 'NISN Siswa / ID Akses Wali / NIP Kepsek',
      identityPlaceholder: 'contoh: 0089271625 / wali.siswa@gmail.com',
      identityIcon: 'person_search',
      identityBadge: 'Akses Khusus Transparansi'
    }
  };

  let currentRole = 'admin';

  function setRole(roleKey) {
    currentRole = roleKey;
    const config = roleConfigs[roleKey];
    if (!config) return;

    // Update Tab Styles with #EAF6FD highlight & #0D5586 border/text
    ['admin', 'bendahara', 'viewer'].forEach(key => {
      const btn = document.getElementById('roleBtn-' + key);
      const icon = document.getElementById('roleIcon-' + key);
      const title = document.getElementById('roleTitle-' + key);
      const sub = document.getElementById('roleSub-' + key);

      if (key === roleKey) {
        btn.className = 'flex flex-col items-center sm:items-start text-left p-space-sm rounded-lg transition-all duration-200 bg-highlight-blue text-sapphire border border-sapphire shadow-sm';
        icon.className = 'material-symbols-outlined text-[19px] text-sapphire';
        title.className = 'font-label-md font-bold text-sapphire leading-tight';
        if (sub) sub.className = 'font-label-sm text-[11px] text-sapphire/80 hidden sm:block truncate w-full';
      } else {
        btn.className = 'flex flex-col items-center sm:items-start text-left p-space-sm rounded-lg transition-all duration-200 bg-transparent text-on-surface-variant hover:bg-surface-container-low border border-transparent';
        icon.className = 'material-symbols-outlined text-[19px] text-on-surface-variant';
        title.className = 'font-label-md font-bold text-on-surface leading-tight';
        if (sub) sub.className = 'font-label-sm text-[11px] text-on-surface-variant hidden sm:block truncate w-full';
      }
    });

    // Update Form elements
    document.getElementById('labelIdentity').innerText = config.identityLabel;
    document.getElementById('badgeIdentityFormat').innerText = config.identityBadge;
    const userInput = document.getElementById('userInput');
    userInput.placeholder = config.identityPlaceholder;

    // Update Role description box
    document.getElementById('roleDescIcon').innerText = config.descIcon;
    document.getElementById('roleDescText').innerHTML = config.desc;
    document.getElementById('identityFieldIcon').innerHTML = `<span class="material-symbols-outlined text-[20px]">${config.identityIcon}</span>`;
  }

  function togglePasswordVisibility() {
    const passField = document.getElementById('passInput');
    const icon = document.getElementById('eyeIcon');
    if (passField.type === 'password') {
      passField.type = 'text';
      icon.innerText = 'visibility_off';
    } else {
      passField.type = 'password';
      icon.innerText = 'visibility';
    }
  }

  function handleLoginSubmit(e) {
    e.preventDefault();
    const identity = document.getElementById('userInput').value;
    const token = document.getElementById('tokenInput').value;
    const roleName = roleConfigs[currentRole].rolePill;

    if (token.length !== 6) {
      alert('Mohon masukkan 6 digit token otorisasi yang valid.');
      return;
    }

    alert(`[KASVIA SYNERGY SECURE AUTH]\n\nMemproses otorisasi masuk sebagai: ${roleName}\nIdentitas: ${identity}\nToken Akses: ${token}\nStatus: Kredensial & Token valid. Mengarahkan ke Dashboard...`);
  }
</script>


</body></html>
